export enum AppSettingsRowKind {
    /**
     * Label, value and an optional button.
     */
    Text = "text",
    /**
     * Label and a segmented choice.
     */
    Choice = "choice",
    /**
     * A muted line (with an optional link).
     */
    Note = "note",
    /**
     * An error line.
     */
    Error = "error",
    /**
     * Label and a text field (`value` is its text).
     */
    Field = "field",
    /**
     * Label and a secure text field (`value` is its text).
     */
    Secret = "secret",
    /**
     * A label over read-only text to copy (`value`), with a Copy button.
     */
    Prompt = "prompt",
    /**
     * A small link-style button (the label).
     */
    Link = "link",
    /**
     * Label and a switch: `options` are `on` and `off`, the active one is
     * its state (a choice drawn as a switch).
     */
    Toggle = "toggle"
}

const FfiConverterTypeAppSettingsRowKind = (() => {
    const ordinalConverter = FfiConverterInt32;
    type TypeName = AppSettingsRowKind;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        read(from: RustBuffer): TypeName {
            switch (ordinalConverter.read(from)) {
                case 1: return AppSettingsRowKind.Text;
                case 2: return AppSettingsRowKind.Choice;
                case 3: return AppSettingsRowKind.Note;
                case 4: return AppSettingsRowKind.Error;
                case 5: return AppSettingsRowKind.Field;
                case 6: return AppSettingsRowKind.Secret;
                case 7: return AppSettingsRowKind.Prompt;
                case 8: return AppSettingsRowKind.Link;
                case 9: return AppSettingsRowKind.Toggle;
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        write(value: TypeName, into: RustBuffer): void {
            switch (value) {
                case AppSettingsRowKind.Text: return ordinalConverter.write(1, into);
                case AppSettingsRowKind.Choice: return ordinalConverter.write(2, into);
                case AppSettingsRowKind.Note: return ordinalConverter.write(3, into);
                case AppSettingsRowKind.Error: return ordinalConverter.write(4, into);
                case AppSettingsRowKind.Field: return ordinalConverter.write(5, into);
                case AppSettingsRowKind.Secret: return ordinalConverter.write(6, into);
                case AppSettingsRowKind.Prompt: return ordinalConverter.write(7, into);
                case AppSettingsRowKind.Link: return ordinalConverter.write(8, into);
                case AppSettingsRowKind.Toggle: return ordinalConverter.write(9, into);
            }
        }
        allocationSize(value: TypeName): number {
            return ordinalConverter.allocationSize(0);
        }
    }
    return new FFIConverter();
})();

