export enum AppEnrollPhase {
    /**
     * Choosing a method.
     */
    Choose = "choose",
    /**
     * The shell runs an interactive sign-in.
     */
    SigningIn = "signingIn",
    /**
     * The shell registers this device with the relay.
     */
    Registering = "registering",
    /**
     * The code shows; the shell polls until an enrolled device approves.
     */
    Waiting = "waiting",
    /**
     * Enrolled.
     */
    Enrolled = "enrolled",
    /**
     * Something failed; Back returns to the choice.
     */
    Failed = "failed"
}

const FfiConverterTypeAppEnrollPhase = (() => {
    const ordinalConverter = FfiConverterInt32;
    type TypeName = AppEnrollPhase;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        read(from: RustBuffer): TypeName {
            switch (ordinalConverter.read(from)) {
                case 1: return AppEnrollPhase.Choose;
                case 2: return AppEnrollPhase.SigningIn;
                case 3: return AppEnrollPhase.Registering;
                case 4: return AppEnrollPhase.Waiting;
                case 5: return AppEnrollPhase.Enrolled;
                case 6: return AppEnrollPhase.Failed;
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        write(value: TypeName, into: RustBuffer): void {
            switch (value) {
                case AppEnrollPhase.Choose: return ordinalConverter.write(1, into);
                case AppEnrollPhase.SigningIn: return ordinalConverter.write(2, into);
                case AppEnrollPhase.Registering: return ordinalConverter.write(3, into);
                case AppEnrollPhase.Waiting: return ordinalConverter.write(4, into);
                case AppEnrollPhase.Enrolled: return ordinalConverter.write(5, into);
                case AppEnrollPhase.Failed: return ordinalConverter.write(6, into);
            }
        }
        allocationSize(value: TypeName): number {
            return ordinalConverter.allocationSize(0);
        }
    }
    return new FFIConverter();
})();

