const FfiConverterTypeAppHostActionId = (() => {
    const ordinalConverter = FfiConverterInt32;
    type TypeName = AppHostActionId;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        read(from: RustBuffer): TypeName {
            switch (ordinalConverter.read(from)) {
                case 1: return AppHostActionId.SetUp;
                case 2: return AppHostActionId.StopSharing;
                case 3: return AppHostActionId.ResumeSharing;
                case 4: return AppHostActionId.Remove;
                case 5: return AppHostActionId.ShareDesktop;
                case 6: return AppHostActionId.HideDesktop;
                case 7: return AppHostActionId.ProvideSpaces;
                case 8: return AppHostActionId.StopProvidingSpaces;
                case 9: return AppHostActionId.SignIn;
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        write(value: TypeName, into: RustBuffer): void {
            switch (value) {
                case AppHostActionId.SetUp: return ordinalConverter.write(1, into);
                case AppHostActionId.StopSharing: return ordinalConverter.write(2, into);
                case AppHostActionId.ResumeSharing: return ordinalConverter.write(3, into);
                case AppHostActionId.Remove: return ordinalConverter.write(4, into);
                case AppHostActionId.ShareDesktop: return ordinalConverter.write(5, into);
                case AppHostActionId.HideDesktop: return ordinalConverter.write(6, into);
                case AppHostActionId.ProvideSpaces: return ordinalConverter.write(7, into);
                case AppHostActionId.StopProvidingSpaces: return ordinalConverter.write(8, into);
                case AppHostActionId.SignIn: return ordinalConverter.write(9, into);
            }
        }
        allocationSize(value: TypeName): number {
            return ordinalConverter.allocationSize(0);
        }
    }
    return new FFIConverter();
})();

