export enum AppTeleportRunPhase {
    /**
     * A step started.
     */
    Started = "started",
    /**
     * Bytes moved.
     */
    Progress = "progress",
    /**
     * A step finished.
     */
    Finished = "finished",
    /**
     * A step failed.
     */
    Failed = "failed",
    /**
     * All done.
     */
    Done = "done"
}

const FfiConverterTypeAppTeleportRunPhase = (() => {
    const ordinalConverter = FfiConverterInt32;
    type TypeName = AppTeleportRunPhase;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        read(from: RustBuffer): TypeName {
            switch (ordinalConverter.read(from)) {
                case 1: return AppTeleportRunPhase.Started;
                case 2: return AppTeleportRunPhase.Progress;
                case 3: return AppTeleportRunPhase.Finished;
                case 4: return AppTeleportRunPhase.Failed;
                case 5: return AppTeleportRunPhase.Done;
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        write(value: TypeName, into: RustBuffer): void {
            switch (value) {
                case AppTeleportRunPhase.Started: return ordinalConverter.write(1, into);
                case AppTeleportRunPhase.Progress: return ordinalConverter.write(2, into);
                case AppTeleportRunPhase.Finished: return ordinalConverter.write(3, into);
                case AppTeleportRunPhase.Failed: return ordinalConverter.write(4, into);
                case AppTeleportRunPhase.Done: return ordinalConverter.write(5, into);
            }
        }
        allocationSize(value: TypeName): number {
            return ordinalConverter.allocationSize(0);
        }
    }
    return new FFIConverter();
})();

