export enum AppAgentStatus {
    /**
     * A turn is running.
     */
    Running = "running",
    /**
     * Waiting for a follow-up.
     */
    Idle = "idle",
    /**
     * Failed.
     */
    Failed = "failed",
    /**
     * Crashed.
     */
    Crashed = "crashed",
    /**
     * Could not be read.
     */
    Unknown = "unknown"
}

const FfiConverterTypeAppAgentStatus = (() => {
    const ordinalConverter = FfiConverterInt32;
    type TypeName = AppAgentStatus;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        read(from: RustBuffer): TypeName {
            switch (ordinalConverter.read(from)) {
                case 1: return AppAgentStatus.Running;
                case 2: return AppAgentStatus.Idle;
                case 3: return AppAgentStatus.Failed;
                case 4: return AppAgentStatus.Crashed;
                case 5: return AppAgentStatus.Unknown;
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        write(value: TypeName, into: RustBuffer): void {
            switch (value) {
                case AppAgentStatus.Running: return ordinalConverter.write(1, into);
                case AppAgentStatus.Idle: return ordinalConverter.write(2, into);
                case AppAgentStatus.Failed: return ordinalConverter.write(3, into);
                case AppAgentStatus.Crashed: return ordinalConverter.write(4, into);
                case AppAgentStatus.Unknown: return ordinalConverter.write(5, into);
            }
        }
        allocationSize(value: TypeName): number {
            return ordinalConverter.allocationSize(0);
        }
    }
    return new FFIConverter();
})();

