// FfiConverter for enum KvSelector
const FfiConverterTypeKvSelector = (() => {
    const ordinalConverter = FfiConverterInt32;
    type TypeName = KvSelector;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        read(from: RustBuffer): TypeName {
            switch (ordinalConverter.read(from)) {
                case 1: return new KvSelector.Item({id: FfiConverterString.read(from) });
                case 2: return new KvSelector.Site({app: FfiConverterString.read(from), site: FfiConverterString.read(from) });
                case 3: return new KvSelector.App({app: FfiConverterString.read(from) });
                case 4: return new KvSelector.Login({site: FfiConverterString.read(from) });
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        write(value: TypeName, into: RustBuffer): void {
            switch (value.tag) {
                case KvSelector_Tags.Item: {
                    ordinalConverter.write(1, into);
                    const inner = value.inner;
                    FfiConverterString.write(inner.id, into);
                    return;
                }
                case KvSelector_Tags.Site: {
                    ordinalConverter.write(2, into);
                    const inner = value.inner;
                    FfiConverterString.write(inner.app, into);
                    FfiConverterString.write(inner.site, into);
                    return;
                }
                case KvSelector_Tags.App: {
                    ordinalConverter.write(3, into);
                    const inner = value.inner;
                    FfiConverterString.write(inner.app, into);
                    return;
                }
                case KvSelector_Tags.Login: {
                    ordinalConverter.write(4, into);
                    const inner = value.inner;
                    FfiConverterString.write(inner.site, into);
                    return;
                }
                default:
                    // Throwing from here means that KvSelector_Tags hasn't matched an ordinal.
                    throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        allocationSize(value: TypeName): number {
            switch (value.tag) {
                case KvSelector_Tags.Item: {
                    const inner = value.inner;
                    let size = ordinalConverter.allocationSize(1);
                    size += FfiConverterString.allocationSize(inner.id);
                    return size;
                }
                case KvSelector_Tags.Site: {
                    const inner = value.inner;
                    let size = ordinalConverter.allocationSize(2);
                    size += FfiConverterString.allocationSize(inner.app);
                    size += FfiConverterString.allocationSize(inner.site);
                    return size;
                }
                case KvSelector_Tags.App: {
                    const inner = value.inner;
                    let size = ordinalConverter.allocationSize(3);
                    size += FfiConverterString.allocationSize(inner.app);
                    return size;
                }
                case KvSelector_Tags.Login: {
                    const inner = value.inner;
                    let size = ordinalConverter.allocationSize(4);
                    size += FfiConverterString.allocationSize(inner.site);
                    return size;
                }
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
    }
    return new FFIConverter();
})();

