export enum KvDecisionTone {
    /**
     * Allowed or delivered.
     */
    Ok = "ok",
    /**
     * Denied, refused, failed.
     */
    Deny = "deny",
    /**
     * Everything else.
     */
    Info = "info"
}

const FfiConverterTypeKvDecisionTone = (() => {
    const ordinalConverter = FfiConverterInt32;
    type TypeName = KvDecisionTone;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        read(from: RustBuffer): TypeName {
            switch (ordinalConverter.read(from)) {
                case 1: return KvDecisionTone.Ok;
                case 2: return KvDecisionTone.Deny;
                case 3: return KvDecisionTone.Info;
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        write(value: TypeName, into: RustBuffer): void {
            switch (value) {
                case KvDecisionTone.Ok: return ordinalConverter.write(1, into);
                case KvDecisionTone.Deny: return ordinalConverter.write(2, into);
                case KvDecisionTone.Info: return ordinalConverter.write(3, into);
            }
        }
        allocationSize(value: TypeName): number {
            return ordinalConverter.allocationSize(0);
        }
    }
    return new FFIConverter();
})();

