/**
 * What a consent item is.
 */
export enum TeleportConsentKind {
    /**
     * An install into the Space (nothing leaves this machine).
     */
    Install = "install",
    /**
     * A host file that leaves this machine.
     */
    File = "file",
    /**
     * A host folder that leaves this machine.
     */
    Folder = "folder",
    /**
     * App state that leaves this machine.
     */
    State = "state",
    /**
     * A secret (cookies, tokens, logins) that leaves this machine.
     */
    Secret = "secret"
}

const FfiConverterTypeTeleportConsentKind = (() => {
    const ordinalConverter = FfiConverterInt32;
    type TypeName = TeleportConsentKind;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        read(from: RustBuffer): TypeName {
            switch (ordinalConverter.read(from)) {
                case 1: return TeleportConsentKind.Install;
                case 2: return TeleportConsentKind.File;
                case 3: return TeleportConsentKind.Folder;
                case 4: return TeleportConsentKind.State;
                case 5: return TeleportConsentKind.Secret;
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        write(value: TypeName, into: RustBuffer): void {
            switch (value) {
                case TeleportConsentKind.Install: return ordinalConverter.write(1, into);
                case TeleportConsentKind.File: return ordinalConverter.write(2, into);
                case TeleportConsentKind.Folder: return ordinalConverter.write(3, into);
                case TeleportConsentKind.State: return ordinalConverter.write(4, into);
                case TeleportConsentKind.Secret: return ordinalConverter.write(5, into);
            }
        }
        allocationSize(value: TypeName): number {
            return ordinalConverter.allocationSize(0);
        }
    }
    return new FFIConverter();
})();

